// The match is not guaranteed to be one byte or one "character" long; the
// caller must ascertain its fitness for purpose.
pub fn tasklist(s: &str) -> Option<(usize, &str, std::ops::Range<usize>)> {
    let mut cursor = 0;
    let mut marker = 0;
    let len = s.len();

    let t1;
    let mut t2;
    let mut yyt1 = 0;

    {
        #[allow(unused_assignments)]
        let mut yych: u8 = 0;
        let mut yystate: usize = 0;
        'yyl: loop {
            match yystate {
                0 => {
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    cursor += 1;
                    match yych {
                        0x09..=0x0D | 0x20 => {
                            yystate = 3;
                            continue 'yyl;
                        }
                        0x5B => {
                            yystate = 4;
                            continue 'yyl;
                        }
                        _ => {
                            yystate = 1;
                            continue 'yyl;
                        }
                    }
                }
                1 => {
                    yystate = 2;
                    continue 'yyl;
                }
                2 => {
                    return None;
                }
                3 => {
                    marker = cursor;
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    match yych {
                        0x09..=0x0D | 0x20 => {
                            cursor += 1;
                            yystate = 5;
                            continue 'yyl;
                        }
                        0x5B => {
                            cursor += 1;
                            yystate = 7;
                            continue 'yyl;
                        }
                        _ => {
                            yystate = 2;
                            continue 'yyl;
                        }
                    }
                }
                4 => {
                    marker = cursor;
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    match yych {
                        0x00..=0x09 | 0x0B..=0x0C | 0x0E..=0x5C | 0x5E..=0xFE => {
                            yyt1 = cursor;
                            cursor += 1;
                            yystate = 8;
                            continue 'yyl;
                        }
                        _ => {
                            yystate = 2;
                            continue 'yyl;
                        }
                    }
                }
                5 => {
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    match yych {
                        0x09..=0x0D | 0x20 => {
                            cursor += 1;
                            yystate = 5;
                            continue 'yyl;
                        }
                        0x5B => {
                            cursor += 1;
                            yystate = 7;
                            continue 'yyl;
                        }
                        _ => {
                            yystate = 6;
                            continue 'yyl;
                        }
                    }
                }
                6 => {
                    cursor = marker;
                    yystate = 2;
                    continue 'yyl;
                }
                7 => {
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    match yych {
                        0x00..=0x09 | 0x0B..=0x0C | 0x0E..=0x5C | 0x5E..=0xFE => {
                            yyt1 = cursor;
                            cursor += 1;
                            yystate = 8;
                            continue 'yyl;
                        }
                        _ => {
                            yystate = 6;
                            continue 'yyl;
                        }
                    }
                }
                8 => {
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    match yych {
                        0x00..=0x09 | 0x0B..=0x0C | 0x0E..=0x5C | 0x5E..=0xFE => {
                            cursor += 1;
                            yystate = 8;
                            continue 'yyl;
                        }
                        0x5D => {
                            cursor += 1;
                            yystate = 9;
                            continue 'yyl;
                        }
                        _ => {
                            yystate = 6;
                            continue 'yyl;
                        }
                    }
                }
                9 => {
                    yych = unsafe {
                        if cursor < len {
                            *s.as_bytes().get_unchecked(cursor)
                        } else {
                            255
                        }
                    };
                    match yych {
                        0x00..=0x08 | 0x0E..=0x1F | 0x21..=0xFE => {
                            yystate = 6;
                            continue 'yyl;
                        }
                        _ => {
                            cursor += 1;
                            yystate = 10;
                            continue 'yyl;
                        }
                    }
                }
                10 => {
                    t1 = yyt1;
                    t2 = cursor;
                    t2 = (t2 as isize + -2) as usize;
                    {
                        if cursor == len + 1 {
                            cursor -= 1;
                        }
                        return Some((cursor, &s[t1..t2], t1..t2));
                    }
                }
                _ => panic!("internal lexer error"),
            }
        }
    }
}

