#[cfg(feature = "phoenix_heex")]
pub fn phoenix_block_expression_end(s: &str) -> bool {
    let bytes = s.as_bytes();
    let len = bytes.len();

    if len < 1 {
        return false;
    }

    let mut i = 0;
    while i < len {
        match bytes[i] {
            b'"' | b'\'' => {
                i = crate::strings::skip_quoted_string(s, i + 1, bytes[i]);
            }
            b'}' => {
                return true;
            }
            _ => i += 1,
        }
    }

    false
}
